class DailyLimits {
    private final Map<String, Long> spent = new HashMap<>();
    private final ReentrantLock lock = new ReentrantLock();

    boolean reserve(String merchant, long cents, long limit) {
        long risk = fraud.score(merchant, cents);            // 1. the slow call, outside the lock (blocks a thread)
        lock.lock();                                          // 2. blocks the thread while waiting
        try {
            long already = spent.getOrDefault(merchant, 0L);
            if (risk > 80 || already + cents > limit) return false;
            spent.put(merchant, already + cents);             // 3. check and reserve together
            return true;
        } finally {
            lock.unlock();
        }
    }
}

kotlin.src:
class DailyLimits {
    private val spent = HashMap<String, Long>()
    private val mutex = Mutex()

    suspend fun reserve(merchant: String, cents: Long, limit: Long): Boolean {
        val risk = fraud.score(merchant, cents)              // 1. the slow call, outside the lock (suspends)
        return mutex.withLock {                              // 2. suspends while waiting, holds no thread
            val already = spent[merchant] ?: 0L
            if (risk > 80 || already + cents > limit) return@withLock false
            spent[merchant] = already + cents                // 3. check and reserve together
            true
        }
    }
}

