class CaptureClient(private val io: CoroutineDispatcher = Dispatchers.IO) {
    suspend fun <T> captureWithRetry(cmd: Capture, call: suspend () -> T): T =
        withContext(io) { retryWithBackoff(times = 5, initialDelay = 200.milliseconds, maxDelay = 2.seconds) { call() } }
}

// 3. in the test
val client = CaptureClient(io = StandardTestDispatcher(testScheduler))

