// Java equivalent: inject the Scheduler, and give the test a virtual one
class CaptureClient {
    private final Scheduler io;
    CaptureClient(Scheduler io) { this.io = io; }

    <T> Mono<T> captureWithRetry(Capture cmd, Mono<T> call) {
        return call.subscribeOn(io)
            .retryWhen(Retry.backoff(4, Duration.ofMillis(200)).maxBackoff(Duration.ofSeconds(2)).jitter(0).scheduler(io));
    }
}

// 3. in the test
VirtualTimeScheduler vts = VirtualTimeScheduler.getOrSet();
CaptureClient client = new CaptureClient(vts);

