@Test
fun `a cancel during the backoff stops the retries`() = runTest {
    var calls = 0
    val job = launch { client.captureWithRetry(cmd) { calls++; throw IOException("503") } }
    advanceTimeBy(300)                 // 4. attempts at 0 and 200 ms; now waiting until 600 ms
    job.cancel()
    advanceUntilIdle()
    assertThat(calls).isEqualTo(2)
}

