@Test
void cancelDuringBackoffStopsRetries() {
    AtomicInteger calls = new AtomicInteger();
    StepVerifier.withVirtualTime(() -> client.captureWithRetry(cmd,
            Mono.<String>fromCallable(() -> { calls.incrementAndGet(); throw new IOException("503"); })))
        .expectSubscription()
        .thenAwait(Duration.ofMillis(300))   // 4. attempts at 0 and 200 ms
        .thenCancel()
        .verify();
    assertThat(calls.get()).isEqualTo(2);
}

