// Java equivalent: a lock-free counter map, and Reactor virtual time for the poller
class MerchantCounts {
    private final ConcurrentHashMap<String, Integer> counts = new ConcurrentHashMap<>();

    void record(String merchant) {
        fraud.check(merchant);                     // blocking: outside any lock
        counts.merge(merchant, 1, Integer::sum);   // one atomic step
    }
}

